-- Compression
SELECT * EXCLUDE ("url", "title"), CASE WHEN "url" IS NULL AND "title" IS NULL THEN TRUE WHEN "url" IS NOT NULL AND "title" IS NOT NULL AND "url" = 'https://ab.wikipedia.org/wiki/' || url_encode("title") THEN TRUE ELSE FALSE END AS "pok", CASE WHEN "url" IS NOT NULL AND "title" IS NOT NULL AND "url" = 'https://ab.wikipedia.org/wiki/' || url_encode("title") THEN url_encode("title") ELSE NULL END AS "slug", CASE WHEN "url" IS NULL AND "title" IS NULL THEN NULL WHEN "url" IS NOT NULL AND "title" IS NOT NULL AND "url" = 'https://ab.wikipedia.org/wiki/' || url_encode("title") THEN NULL ELSE "url" END AS "url_e", CASE WHEN "url" IS NULL AND "title" IS NULL THEN NULL WHEN "url" IS NOT NULL AND "title" IS NOT NULL AND "url" = 'https://ab.wikipedia.org/wiki/' || url_encode("title") THEN NULL ELSE "title" END AS "title_e" FROM source;

-- Reconstruction
SELECT * EXCLUDE ("pok", "slug", "url_e", "title_e"), CASE WHEN "pok" AND "slug" IS NOT NULL THEN 'https://ab.wikipedia.org/wiki/' || "slug" WHEN "pok" THEN NULL ELSE "url_e" END AS "url", CASE WHEN "pok" AND "slug" IS NOT NULL THEN url_decode("slug") WHEN "pok" THEN NULL ELSE "title_e" END AS "title" FROM compressed;
